?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Settings - Games Club BD</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#f3f4f6;font-family:Inter,Arial,sans-serif;color:#1f2937}.wrap{max-width:760px;margin:36px auto;padding:0 16px}.card{border:0;border-radius:16px;box-shadow:0 4px 18px #0000000a}.btn-primary{background:#1976d2;border:0}</style></head><body><main class="wrap"><a class="text-decoration-none" href="index.php">← Admin dashboard</a><h1 class="h3 fw-bold mt-3 mb-4">App Settings</h1><section class="card p-4 p-md-5"><h2 class="h5 text-primary mb-2">Goriber Pay</h2><p class="text-secondary">Payment deposits are processed through Goriber Pay only.</p><form id="settings-form"><label for="brand-key" class="form-label">Brand Key</label><input class="form-control mb-3" id="brand-key" name="brand_key" type="password" value="<?= h($key) ?>" autocomplete="new-password" required><button class="btn btn-primary px-4" type="submit">Save Brand Key</button><span id="result" class="ms-3" role="status"></span></form></section></main><script>const csrf=<?= json_encode($csrf) ?>;document.getElementById('settings-form').addEventListener('submit',async e=>{e.preventDefault();const result=document.getElementById('result');result.textContent='Saving…';try{const r=await fetch('../api/save_settings.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({brand_key:document.getElementById('brand-key').value})});const d=await r.json();result.textContent=d.ok?'Saved.':(d.error||'Save failed.');result.className='ms-3 '+(d.ok?'text-success':'text-danger')}catch(_){result.textContent='Request failed.';result.className='ms-3 text-danger'}});</script></body></html>
